import {
	getV1BodyMeasurementsDatePathParamsSchema,
	getV1BodyMeasurementsQueryParamsSchema,
	getV1ExerciseHistoryExercisetemplateidPathParamsSchema,
	getV1ExerciseTemplatesExercisetemplateidPathParamsSchema,
	getV1WorkoutsEventsQueryParamsSchema,
	getV1RoutinesQueryParamsSchema,
	getV1RoutinesRoutineidPathParamsSchema,
	getV1WorkoutsQueryParamsSchema,
	getV1WorkoutsWorkoutidPathParamsSchema,
} from "@hevy-mcp/hevy-client/schemas";
import { z } from "zod";

const stringSchema = z.string();

function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}

interface UsageInput {
	[key: string]: string | undefined;
}

export interface CliArgs {
	command?: string;
	subcommand?: string;
	positionals: string[];
	options: Partial<Record<string, string | boolean>>;
}

export class UsageError extends Error {}

export class ConfigurationError extends Error {}

function stringOption(value: string | boolean | undefined): string | undefined {
	return isString(value) ? value : undefined;
}

function parseForUsage<T>(
	schema: z.ZodType<T>,
	value: string | undefined | UsageInput,
	labels: string | Record<string, string>,
	messages: Record<string, string> = {},
): T {
	try {
		return schema.parse(value);
	} catch (error) {
		if (!(error instanceof z.ZodError)) throw error;
		const issue = error.issues[0];
		const key = isString(issue?.path[0]) ? issue.path[0] : undefined;
		const label = isString(labels) ? labels : (key && labels[key]) || "Value";
		throw new UsageError(
			`${label} ${messages[key ?? "_"] ?? issue?.message ?? "is invalid"}`,
		);
	}
}

const safePositiveInteger = (message: string) =>
	z.number().int().refine(Number.isSafeInteger, message).min(1, message);

const paginationSchema = (
	source:
		| typeof getV1WorkoutsQueryParamsSchema
		| typeof getV1RoutinesQueryParamsSchema
		| typeof getV1BodyMeasurementsQueryParamsSchema,
) =>
	z.object({
		page: source.shape.page
			.pipe(safePositiveInteger("must be a positive integer"))
			.default(1),
		pageSize: source.shape.pageSize
			.pipe(
				z
					.number()
					.int()
					.refine(
						Number.isSafeInteger,
						"must be a positive integer no greater than 10",
					)
					.min(1, "must be a positive integer no greater than 10")
					.max(10, "must be a positive integer no greater than 10"),
			)
			.default(5),
	});

const eventOptionsSchema = z.object({
	page: getV1WorkoutsEventsQueryParamsSchema.shape.page
		.pipe(safePositiveInteger("must be a positive integer"))
		.default(1),
	pageSize: getV1WorkoutsEventsQueryParamsSchema.shape.pageSize
		.pipe(
			z
				.number()
				.int()
				.refine(
					Number.isSafeInteger,
					"must be a positive integer no greater than 10",
				)
				.min(1, "must be a positive integer no greater than 10")
				.max(10, "must be a positive integer no greater than 10"),
		)
		.default(5),
	since: getV1WorkoutsEventsQueryParamsSchema.shape.since.pipe(
		z.iso.datetime({
			offset: true,
			message: "must be an ISO timestamp",
		}),
	),
});

const historyDateSchema = z.iso.datetime({
	offset: true,
	message: "must be an ISO timestamp",
});
const exerciseHistoryOptionsSchema = z.object({
	start_date: z.string().pipe(historyDateSchema).optional(),
	end_date: z.string().pipe(historyDateSchema).optional(),
});

const safePathSegment = (message: string) =>
	z
		.string()
		.trim()
		.refine((value) => value.length > 0 && !/[/?#]/.test(value), message);
const workoutIdSchema =
	getV1WorkoutsWorkoutidPathParamsSchema.shape.workoutId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const routineIdSchema =
	getV1RoutinesRoutineidPathParamsSchema.shape.routineId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const exerciseIdSchema =
	getV1ExerciseTemplatesExercisetemplateidPathParamsSchema.shape.exerciseTemplateId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const exerciseHistoryIdSchema =
	getV1ExerciseHistoryExercisetemplateidPathParamsSchema.shape.exerciseTemplateId.pipe(
		safePathSegment("is required and must be a safe path segment"),
	);
const searchQuerySchema = safePathSegment(
	"is required and must be a safe search term",
);
const measurementDateSchema =
	getV1BodyMeasurementsDatePathParamsSchema.shape.date;
const weeksSchema = z.coerce
	.number()
	.max(520, "must be a positive integer no greater than 520")
	.pipe(safePositiveInteger("must be a positive integer no greater than 520"))
	.default(1);
const searchOptionsSchema = z.object({
	maxPages: z.coerce
		.number()
		.max(100, "must be a positive integer no greater than 100")
		.pipe(safePositiveInteger("must be a positive integer"))
		.default(10),
});

export function parsePagination(
	args: CliArgs,
	source:
		| typeof getV1WorkoutsQueryParamsSchema
		| typeof getV1RoutinesQueryParamsSchema
		| typeof getV1BodyMeasurementsQueryParamsSchema = getV1WorkoutsQueryParamsSchema,
): {
	page: number;
	pageSize: number;
} {
	return parseForUsage(
		paginationSchema(source),
		{
			page: stringOption(args.options.page),
			pageSize: stringOption(args.options["page-size"]),
		},
		{ page: "--page", pageSize: "--page-size" },
		{
			page: "must be a positive integer",
			pageSize: "must be a positive integer no greater than 10",
		},
	);
}

export function parseWorkoutEventsOptions(args: CliArgs): {
	page: number;
	pageSize: number;
	since: string;
} {
	return parseForUsage(
		eventOptionsSchema,
		{
			page: stringOption(args.options.page),
			pageSize: stringOption(args.options["page-size"]),
			since: stringOption(args.options.since),
		},
		{ page: "--page", pageSize: "--page-size", since: "--since" },
		{
			page: "must be a positive integer",
			pageSize: "must be a positive integer no greater than 10",
			since: "must be an ISO timestamp",
		},
	);
}

export function parseExerciseHistoryOptions(
	args: CliArgs = { positionals: [], options: {} },
): {
	start_date?: string;
	end_date?: string;
} {
	return parseForUsage(
		exerciseHistoryOptionsSchema,
		{
			start_date: stringOption(args.options["start-date"]),
			end_date: stringOption(args.options["end-date"]),
		},
		{ start_date: "--start-date", end_date: "--end-date" },
		{
			start_date: "must be an ISO timestamp",
			end_date: "must be an ISO timestamp",
		},
	);
}

export function parseWorkoutId(value: string | undefined): string {
	return parseForUsage(workoutIdSchema, value, "Workout ID", {
		_: "is required",
	});
}

export function parseRoutineId(value: string | undefined): string {
	return parseForUsage(routineIdSchema, value, "Routine ID", {
		_: "is required",
	});
}

export function parseExerciseId(value: string | undefined): string {
	return parseForUsage(exerciseIdSchema, value, "Exercise ID", {
		_: "is required",
	});
}

export function parseExerciseHistoryId(value: string | undefined): string {
	return parseForUsage(exerciseHistoryIdSchema, value, "Exercise ID", {
		_: "is required",
	});
}

export function parseMeasurementDate(value: string | undefined): string {
	return parseForUsage(measurementDateSchema, value, "Measurement date", {
		_: "must be an ISO date",
	});
}

export function parseSearchQuery(value: string | undefined): string {
	return parseForUsage(searchQuerySchema, value, "Search query", {
		_: "is required",
	}).toLocaleLowerCase();
}

export function parseSearchMaxPages(args: CliArgs): number {
	return parseForUsage(
		searchOptionsSchema,
		{ maxPages: stringOption(args.options["max-pages"]) },
		{ maxPages: "--max-pages" },
		{ maxPages: "must be a positive integer no greater than 100" },
	).maxPages;
}

export function parseWeeks(args: CliArgs): number {
	return parseForUsage(
		weeksSchema,
		stringOption(args.options.weeks),
		"--weeks",
		{
			_: "must be a positive integer no greater than 520",
		},
	);
}

export function requireMutationConfirmation(args: CliArgs): void {
	if (args.options.yes !== true)
		throw new UsageError("Mutation requires --yes");
}
import { ConfigurationError } from "./arguments.js";

export function getApiKey(env: Record<string, string | undefined>): string {
	const key = env.HEVY_API_KEY?.trim();
	if (!key)
		throw new ConfigurationError(
			"HEVY_API_KEY is required; set it in the environment",
		);
	return key;
}
import { DEFAULT_API_TIMEOUT_MS } from "@hevy-mcp/hevy-client";
import { runCli } from "./main.js";

const lifecycleController = new AbortController();
const abortOnSignal = (signal: NodeJS.Signals) => {
	lifecycleController.abort(
		new DOMException(`CLI shutdown requested by ${signal}`, "AbortError"),
	);
};
process.once("SIGINT", abortOnSignal);
process.once("SIGTERM", abortOnSignal);

try {
	const exitCode = await runCli({
		argv: process.argv.slice(2),
		execution: {
			signal: lifecycleController.signal,
			deadline: Date.now() + DEFAULT_API_TIMEOUT_MS,
		},
	});
	if (exitCode !== 0) process.exitCode = exitCode;
} finally {
	process.removeListener("SIGINT", abortOnSignal);
	process.removeListener("SIGTERM", abortOnSignal);
}
import {
	ApiError,
	HevyHttpError,
	isHevyHttpError,
	NetworkError,
	NotFoundError,
	RateLimitError,
	SAFE_OBSERVATION_CODES,
	ValidationError,
} from "@hevy-mcp/hevy-client";
import {
	EmptyMeasurementUpdateError,
	PaginationMismatchError,
	TemplatesSearchValidationError,
	TrainingSummaryDataError,
	TrainingSummaryValidationError,
	WorkoutPayloadError,
	WorkoutPrivacyError,
} from "@hevy-mcp/operations";
import { ConfigurationError, UsageError } from "./arguments.js";

export class ApiResponseError extends Error {}

export const EXIT = { configuration: 1, usage: 2, api: 3, network: 4 } as const;

export interface CliDiagnostic {
	code: number;
	message: string;
	error_code?: string;
	outcome?: string;
	phase?: string;
	operation_safety?: string;
	commit_state?: string;
	safe_to_retry?: boolean;
}

type TaggedClientError =
	| ApiError
	| NetworkError
	| NotFoundError
	| RateLimitError
	| ValidationError;

const SAFE_ERROR_CODES = new Set([
	...SAFE_OBSERVATION_CODES,
	"HEVY_INVALID_ENDPOINT",
]);

type OperationDomainError =
	| EmptyMeasurementUpdateError
	| PaginationMismatchError
	| TemplatesSearchValidationError
	| TrainingSummaryDataError
	| TrainingSummaryValidationError
	| WorkoutPayloadError
	| WorkoutPrivacyError;

function isTaggedClientError(
	error: Error | string,
): error is TaggedClientError {
	return (
		error instanceof ApiError ||
		error instanceof NetworkError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError
	);
}

function isOperationDomainError(
	error: Error | string,
): error is OperationDomainError {
	return (
		error instanceof EmptyMeasurementUpdateError ||
		error instanceof TrainingSummaryDataError ||
		error instanceof PaginationMismatchError ||
		error instanceof TemplatesSearchValidationError ||
		error instanceof TrainingSummaryValidationError ||
		error instanceof WorkoutPayloadError ||
		error instanceof WorkoutPrivacyError
	);
}

function projectExecutionFields(fields: {
	outcome?: CliDiagnostic["outcome"];
	phase?: CliDiagnostic["phase"];
	operationSafety?: CliDiagnostic["operation_safety"];
	commitState?: CliDiagnostic["commit_state"];
	safeToRetry?: CliDiagnostic["safe_to_retry"];
	code?: string;
}): Omit<CliDiagnostic, "code" | "message"> {
	const execution = {
		outcome: fields.outcome ?? "terminal_failure",
		phase: fields.phase ?? "before-dispatch",
		operation_safety: fields.operationSafety ?? "read",
		commit_state: fields.commitState ?? "not_sent",
		safe_to_retry: fields.safeToRetry ?? false,
	};
	const errorCode =
		fields.code !== undefined && SAFE_ERROR_CODES.has(fields.code)
			? fields.code
			: undefined;
	return errorCode === undefined
		? execution
		: { ...execution, error_code: errorCode };
}

function executionFields(
	error: Error | string,
): Omit<CliDiagnostic, "code" | "message"> {
	if (isHevyHttpError(error)) {
		return projectExecutionFields({
			outcome: error.outcome,
			phase: error.phase_name,
			operationSafety: error.operation_safety,
			commitState: error.commit_state,
			safeToRetry: error.safe_to_retry,
			code: error.code,
		});
	}
	if (isTaggedClientError(error)) {
		return projectExecutionFields({
			outcome: error.outcome,
			phase: error.phase,
			operationSafety: error.operationSafety,
			commitState: error.commitState,
			safeToRetry: error.safeToRetry,
			code: error.code,
		});
	}
	return {};
}

export function diagnostic(error: Error | string): CliDiagnostic {
	if (error instanceof ConfigurationError)
		return { code: EXIT.configuration, message: error.message };
	if (error instanceof ApiResponseError)
		return {
			code: EXIT.api,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
			...executionFields(error),
		};
	if (isOperationDomainError(error)) {
		if (
			error instanceof PaginationMismatchError ||
			error instanceof WorkoutPayloadError ||
			error instanceof TrainingSummaryDataError
		) {
			return {
				code: EXIT.api,
				message:
					error instanceof PaginationMismatchError
						? "The API returned invalid pagination metadata"
						: error.message,
			};
		}
		return { code: EXIT.usage, message: error.message };
	}
	if (
		error instanceof HevyHttpError ||
		isHevyHttpError(error) ||
		isTaggedClientError(error)
	) {
		const status = "status" in error ? error.status : undefined;
		if (status === 401)
			return {
				code: EXIT.api,
				message: "Authentication failed; check HEVY_API_KEY",
				...executionFields(error),
			};
		if (status !== undefined)
			return {
				code: EXIT.api,
				message: `Hevy API request failed (HTTP ${status})`,
				...executionFields(error),
			};
		return {
			code: EXIT.network,
			message:
				("code" in error ? error.code : undefined) === "ETIMEDOUT"
					? "Hevy API request timed out"
					: "Unable to reach the Hevy API",
			...executionFields(error),
		};
	}
	if (error instanceof UsageError)
		return {
			code: EXIT.usage,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
		};
	return { code: EXIT.usage, message: "Command failed" };
}
import { readFile } from "node:fs/promises";
import { z } from "zod";
import { UsageError } from "./arguments.js";

const jsonValueSchema = z.json();
const stringifiedJsonSchema = z.string().transform((value) => {
	try {
		return jsonValueSchema.parse(JSON.parse(value));
	} catch {
		// Preserve invalid values so the owning schema reports the field path.
		return value;
	}
});
const exercisesInputSchema = z.union([stringifiedJsonSchema, z.unknown()]);
const workoutExercisesInputSchema = z
	.object({
		workout: z.object({ exercises: exercisesInputSchema }).passthrough(),
	})
	.passthrough();
const routineExercisesInputSchema = z
	.object({
		routine: z.object({ exercises: exercisesInputSchema }).passthrough(),
	})
	.passthrough();
const mutationInputBoundarySchema = z.union([
	workoutExercisesInputSchema,
	routineExercisesInputSchema,
	z.unknown(),
]);

export type DataSourceReader = (source: string) => Promise<string>;

async function readStdin(): Promise<string> {
	const chunks: Buffer[] = [];
	for await (const chunk of process.stdin) {
		chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
	}
	return Buffer.concat(chunks).toString("utf8");
}

export const readDataSource: DataSourceReader = (source) =>
	source === "-" ? readStdin() : readFile(source, "utf8");

function schemaDiagnostic(error: z.ZodError): string {
	const issue = error.issues[0];
	const path = issue?.path.join(".");
	return path
		? `--data.${path} ${issue.message}`
		: `--data ${issue?.message ?? "is invalid"}`;
}

export async function loadMutationInput<T>(
	value: string,
	schema: z.ZodType<T>,
	reader: DataSourceReader = readDataSource,
): Promise<T> {
	let sourceValue = value;
	if (value.startsWith("@")) {
		const source = value.slice(1);
		if (source.length === 0)
			throw new UsageError("--data source is required after @");
		try {
			sourceValue = await reader(source);
		} catch {
			throw new UsageError(`Unable to read --data source "${source}"`);
		}
	}

	let parsed: unknown;
	try {
		parsed = JSON.parse(sourceValue);
	} catch {
		throw new UsageError("--data must contain valid JSON");
	}

	try {
		// Keep the CLI's existing --data input contract at this adapter boundary;
		// Operations schemas remain transport-neutral and require real arrays.
		return schema.parse(mutationInputBoundarySchema.parse(parsed));
	} catch (error) {
		if (error instanceof z.ZodError)
			throw new UsageError(schemaDiagnostic(error));
		throw error;
	}
}
import {
	createHevyClient,
	type HevyClient,
	type HevyExecutionOptions,
} from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import { getApiKey } from "./auth.js";
import { diagnostic, EXIT } from "./errors.js";
import { readDataSource, type DataSourceReader } from "./input.js";
import { runRoutes, type CliState } from "./routes.js";
import { writeResult, type Streams } from "./output/write.js";
export interface RunCliOptions {
	argv: string[];
	env?: Record<string, string | undefined>;
	clientFactory?: (key: string) => HevyClient;
	now?: () => Date;
	readDataSource?: DataSourceReader;
	streams?: Streams;
	execution?: HevyExecutionOptions;
}

const cliCommands = new Set([
	"user",
	"workouts",
	"routines",
	"exercises",
	"folders",
	"measurements",
	"summary",
]);
const cliSubcommands = new Set([
	"list",
	"get",
	"count",
	"events",
	"search",
	"history",
	"create",
	"update",
]);

function writeCliEvent(
	streams: Streams,
	argv: string[],
	startedAt: number,
	result: {
		outcome: "success" | "failure";
		exitCode: number;
		errorCode?: string;
	},
): void {
	const command = cliCommands.has(argv[0] ?? "") ? argv[0] : undefined;
	const subcommand = cliSubcommands.has(argv[1] ?? "") ? argv[1] : undefined;
	try {
		streams.stderr(
			`${JSON.stringify({
				timestamp: new Date().toISOString(),
				level: result.outcome === "success" ? "info" : "error",
				event: "cli.command",
				outcome: result.outcome,
				exit_code: result.exitCode,
				duration_ms: Math.round(performance.now() - startedAt),
				command: command ?? "unknown",
				subcommand: subcommand ?? "unknown",
				error_code: result.errorCode ?? null,
			})}\n`,
		);
	} catch {
		// Optional CLI logging must not change the command result.
	}
}

export async function runCli(options: RunCliOptions): Promise<number> {
	const env = options.env ?? globalThis.process.env;
	const streams = options.streams ?? {
		stdout: (text) => process.stdout.write(text),
		stderr: (text) => process.stderr.write(text),
	};
	const state: CliState = {};
	const stricliProcess = {
		stdout: { write: streams.stdout },
		stderr: { write: streams.stderr },
		exitCode: undefined as number | undefined,
	};
	const context = {
		process: stricliProcess,
		state,
		now: options.now ?? (() => new Date()),
		readDataSource: options.readDataSource ?? readDataSource,
		client: undefined as HevyClient | undefined,
		operations: undefined as HevyOperations | undefined,
		execution: options.execution,
	};
	const metaCommand = options.argv.some((value) =>
		["--help", "-h", "--version", "-v"].includes(value),
	);
	const logEnabled = !metaCommand && env.HEVY_CLI_LOG === "true";
	const startedAt = performance.now();
	try {
		if (!metaCommand) {
			const key = getApiKey(env);
			const createdClient = (
				options.clientFactory ?? ((apiKey) => createHevyClient({ apiKey }))
			)(key);
			context.client = createdClient;
			context.operations = createOperations(createdClient, {
				trainingSummaryMaxWeeks: 520,
				trainingSummaryStrictPagination: true,
			});
		}
		const exitCode = await runRoutes(options.argv, context);
		if (state.error !== undefined) throw state.error;
		if (exitCode !== 0) {
			if (logEnabled)
				writeCliEvent(streams, options.argv, startedAt, {
					outcome: "failure",
					exitCode: EXIT.usage,
				});
			return EXIT.usage;
		}
		if (state.result !== undefined) {
			const json = options.argv.includes("--json");
			writeResult(state.result, json, streams);
		}
		if (logEnabled)
			writeCliEvent(streams, options.argv, startedAt, {
				outcome: "success",
				exitCode: 0,
			});
		return 0;
	} catch (error) {
		const normalizedError = error instanceof Error ? error : String(error);
		const failure = diagnostic(normalizedError);
		if (logEnabled)
			writeCliEvent(streams, options.argv, startedAt, {
				outcome: "failure",
				exitCode: failure.code,
				errorCode: failure.error_code,
			});
		if (options.argv.includes("--json")) {
			streams.stderr(`${JSON.stringify(failure)}\n`);
		} else {
			streams.stderr(`${failure.message}\n`);
		}
		return failure.code;
	}
}

