	id: string,
	input: TInput,
	execution: HevyExecutionOptions | undefined,
): Promise<TOutput> {
	const resolved = requireOperation(operation, id);
	return collapse(resolved.effect(input, execution));
}

export function runOperationWithoutInput<TOutput>(
	operation: OptionsOperation<TOutput> | undefined,
	id: string,
	execution: HevyExecutionOptions | undefined,
): Promise<TOutput> {
	const resolved = requireOperation(operation, id);
	return collapse(resolved.effect(execution));
}

export function list(
	data: ApiObject,
	source: string,
	output: string,
	page: number,
): ApiObject {
	const count = z.number().safeParse(data.page_count).data;
	const items = Array.isArray(data[source]) ? data[source] : [];
	if (
		count === undefined ||
		!Number.isSafeInteger(count) ||
		count < 0 ||
		(count === 0 && items.length > 0) ||
		(data.page !== undefined && data.page !== page)
	)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	if (count > 0 && page > count)
		throw new UsageError("Requested page exceeds the API page count");
	return pageEnvelope(data, output, items);
}

export function mutationData(args: CliArgs): string {
	const parsed = z.string().safeParse(args.options.data);
	if (!parsed.success) throw new UsageError("--data is required");
	return parsed.data;
}
import type { HevyClient, HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import { UsageError, type CliArgs } from "../arguments.js";
import type { DataSourceReader } from "../input.js";
import { executeFolderCreate } from "./folders.js";
import { executeMeasurements } from "./measurements.js";
import { executeRoutines } from "./routines.js";
import { executeSummary } from "./summary.js";
import { executeExercises } from "./templates.js";
import { executeUser } from "./user.js";
import { executeWorkouts } from "./workouts.js";
import type { CommandContext } from "./context.js";
import { readDataSource as defaultDataSourceReader } from "../input.js";

export async function execute(
	args: CliArgs,
	client: HevyClient,
	now = () => new Date(),
	readDataSource: DataSourceReader = defaultDataSourceReader,
	operations: HevyOperations = createOperations(client, {
		trainingSummaryMaxWeeks: 520,
		trainingSummaryStrictPagination: true,
	}),
	execution?: HevyExecutionOptions,
): Promise<unknown> {
	const context: CommandContext = {
		args,
		now,
		readDataSource,
		operations,
		execution,
	};
	if (args.command === "user" && !args.subcommand) return executeUser(context);
	if (args.command === "workouts") return executeWorkouts(context);
	if (args.command === "routines") return executeRoutines(context);
	if (args.command === "exercises") return executeExercises(context);
	if (args.command === "measurements") return executeMeasurements(context);
	if (args.command === "folders" && args.subcommand === "create")
		return executeFolderCreate(context);
	if (args.command === "summary") return executeSummary(context);
	throw new UsageError("Unknown command; run hevy --help");
}
import { z } from "zod";

const numberSchema = z.number();

export type ApiValue =
	| string
	| number
	| boolean
	| null
	| undefined
	| object
	| ApiValue[];
export type ApiObject = { [key: string]: ApiValue };

export interface PaginationEnvelope<T> {
	page: number;
	page_count: number;
	[key: string]: number | T[];
}

export interface SearchResult<T> {
	query: string;
	matches: T[];
	pages_scanned: number;
	complete: boolean;
}

export interface SummaryResult {
	weeks: number;
	start_date: string;
	end_date: string;
	workout_count: number;
	total_duration_seconds: number;
	exercise_count: number;
	set_count: number;
	total_volume_kg: number;
	pages_scanned: number;
	complete: boolean;
}

export function pageEnvelope(
	data: ApiObject,
	key: string,
	items: readonly ApiValue[],
): ApiObject {
	return {
		page: numberSchema.safeParse(data.page).success ? data.page : 1,
		page_count: numberSchema.safeParse(data.page_count).success
			? data.page_count
			: 0,
		[key]: items,
	};
}
import { z } from "zod";

const objectSchema = z.object({}).passthrough();
const stringSchema = z.string();
function isObject<T>(value: T): value is T & object {
	return objectSchema.safeParse(value).success;
}
function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}

function scalar<T>(value: T): string {
	if (value === null || value === undefined) return "null";
	if (isObject(value)) return JSON.stringify(value);
	return isString(value) ? value : (JSON.stringify(value) ?? "");
}

export function human<T>(value: T): string {
	if (Array.isArray(value))
		return value.length
			? value.map((item) => human(item)).join("\n")
			: "No results.";
	if (!value || !isObject(value)) return scalar(value);
	const lines: string[] = [];
	for (const [key, item] of Object.entries(value)) {
		if (Array.isArray(item)) {
			lines.push(`${key}: ${item.length} item(s)`);
			for (const child of item.slice(0, 20)) {
				if (child && isObject(child))
					lines.push(
						`  - ${Object.entries(child)
							.map(([k, v]) => `${k}=${scalar(v)}`)
							.join(", ")}`,
					);
				else lines.push(`  - ${scalar(child)}`);
			}
		} else if (item && isObject(item)) {
			lines.push(`${key}:`);
			lines.push(
				...human(item)
					.split("\n")
					.map((line) => `  ${line}`),
			);
		} else lines.push(`${key}: ${scalar(item)}`);
	}
	return lines.join("\n") || "No results.";
}
import { human } from "./human.js";

export interface Streams {
	stdout: (text: string) => void;
	stderr: (text: string) => void;
}
export function writeResult<T>(
	value: T,
	json: boolean,
	streams: Streams,
): void {
	streams.stdout(`${json ? JSON.stringify(value) : human(value)}\n`);
}

