async function go(label: string, argv: string[], respond: (req: Request, n: number) => Promise<Response>, env: Record<string,string> = { HEVY_API_KEY: "k" }) {
	let out = ""; let err = ""; const calls: string[] = []; let n = 0;
	const f = (async (i: RequestInfo | URL, init?: RequestInit) => { const r = new Request(i, init); calls.push(`${r.method} ${new URL(r.url).pathname}${new URL(r.url).search}`); return respond(r, n++); }) as typeof fetch;
	const code = await runCli({ argv, env,
		streams: { stdout: (t) => { out += t; }, stderr: (t) => { err += t; } },
		clientFactory: (k) => createHevyClient({ apiKey: k, fetch: f, sleep: async () => {} }) });
	appendFileSync(LOG, JSON.stringify({ label, code, out: out.slice(0, 500), err: err.slice(0, 400), calls }) + "\n");
}
const j = (b: unknown, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { "content-type": "application/json" } });
const w = { id: "w1", title: "T", description: null, start_time: "2026-01-01T00:00:00Z", end_time: "2026-01-01T01:00:00Z", updated_at: "2026-01-01T01:00:00Z", created_at: "2026-01-01T01:00:00Z", exercises: [] };
