	await go("list 404 page3", ["workouts", "list", "--page", "3", "--json"], async () => j({ error: "nf" }, 404));
	await go("bare", [], async () => j({}), {});
	await go("bare workouts", ["workouts"], async () => j({}), {});
	await go("since -h", ["workouts", "events", "--since", "-h"], async () => j({}), {});
	await go("json=true", ["workouts", "list", "--json=true"], async () => j({ page: 1, page_count: 1, workouts: [] }));
